{
    "API_calls": [],
    "collected_information": {
        "Environment_Setup": {
            "Languages_and_Dependencies": {
                "Python_code_formatting": "ruff==0.15.22",
                "C++_code_formatting": "clang-format==18.1.8"
            },
            "Commands_for_Running_Tests": {
                "Python": "cd python && pytest -v -s .",
                "Java": "cd java && mvn -T10 clean test",
                "C++": "bazel test $(bazel query //...)",
                "GoLang": "cd go/fory && go test -v ./... && go test -v fory_xlang_test.go",
                "Rust": {
                    "Default": "cd rust && cargo test",
                    "Specific_Test": [
                        "cargo test -p tests --test $test_file $test_method",
                        "cargo test --test mod $dir$::$test_file::$test_method",
                        "RUST_BACKTRACE=1 FORY_PANIC_ON_ERROR=1 cargo test --test mod $dir$::$test_file::$test_method"
                    ]
                },
                "JavaScript": ["cd javascript && npm run test", "npx jest crossLanguage.test.ts"]
            },
            "Environment_Variables_Java": {
                "FORY_CODE_DIR": "Directory for generated code.",
                "ENABLE_FORY_GENERATED_CLASS_UNIQUE_ID": "Appends unique IDs for generated files ('true' by default)."
            },
            "Debugging_Commands_Python": [
                "FORY_DEBUG=true python setup.py build_ext --inplace",
                "cython --cplus -a pyfory/serialization.pyx"
            ],
            "Runtime_Requirements": {
                "Java_Modules": {
                    "Java_8": "fory-core",
                    "Java_11+": "fory-format"
                },
                "Python_Version": "sys.version_info.major and sys.version_info.minor"
            }
        },
        "Dependencies": {
            "Python": {
                "setup.py": {
                    "No_Explicit_Dependencies": "Adapts to current Python version using sys.version_info.",
                    "Environment_Variables": {
                        "FORY_DEBUG": "Alters build behavior when set to 'true'.",
                        "BAZEL_BUILD_EXT": "Controls whether Bazel builds extensions (defaults to 'true')."
                    }
                }
            },
            "Java": {
                "pom.xml": {
                    "Dependencies": [
                        "Google Guava: 32.1.2-jre",
                        "Janino: 3.1.12",
                        "JSR305: 3.0.2",
                        "SLF4J: 2.0.12",
                        "Commons Codec: 1.13",
                        "Lombok: 1.18.38",
                        "Mockito Core: 4.11.0",
                        "TestNG: 7.5.1",
                        "JUnit: 4.13.1",
                        "Apache Ant: 1.10.12"
                    ],
                    "Configuration_Properties": {
                        "Compiler_Source/Target_Version": "1.8",
                        "Profiles": "Supports JDK 8, 11, 21+ with module configurations."
                    }
                }
            },
            "JavaScript": {
                "package.json": {
                    "Dependencies": {
                        "@types/node": "18.19.130 (Exact Version)",
                        "jest": "^30.4.2",
                        "tslint": "^8.66.0",
                        "prettier": "^3.9.4"
                    }
                }
            },
            "Rust": {
                "Cargo.toml": {
                    "Rust_Version": "1.70",
                    "Edition": "2021",
                    "Dependencies": [
                        "fory-core: Path = 'fory-core', Version = '1.8.0-alpha.0'",
                        "fory-derive: Path = 'fory-derive', Version = '1.8.0-alpha.0'"
                    ]
                }
            }
        }
    },
    "terminate": true
}
